mapper.select:
select * from ( SELECT a.log_id logId, a.user_id userId, a.business_step businessStep, a.log_flag logFlag, a.content, DATE_FORMAT( a.log_time, '%Y-%m-%d' ) logTime, a.log_file_addr logFileAddr, DATE_FORMAT( a.create_time, '%Y-%m-%d %H:%i:%s' ) createTime, cb1.code_name businessStepName, cb2.code_name logFlagName, u.user_name userName, u.user_no userNo, u.user_tel userTel FROM cust_user_ecg_exception_log a LEFT JOIN comm_base_code_detail cb1 ON a.business_step = cb1.code_id AND cb1.type_no = 'SYS101' LEFT JOIN comm_base_code_detail cb2 ON a.log_flag = cb2.code_id AND cb2.type_no = 'SYS101' LEFT JOIN cust_userinfo u ON a.user_id = u.user_id )temp where 1=1
and DATE_FORMAT(logTime,'%Y-%m-%d') >= #{tm}
and DATE_FORMAT(logTime,'%Y-%m-%d') <= #{tm}
and ${key} like CONCAT('%',#{tm,jdbcType=VARCHAR}, '%')
order by ${column} ${order}
order by logTime desc
